import type { InputProps } from "./input.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Input";

// Generate child element class names for the component, should match available style slots
export const InputClasses = {
  root: "exp-textura_input",
  sm: "exp-textura_input_sm",
  inputWrapper: "exp-textura_input_wrapper",
  input: "exp-textura_input_input",
  characterCount: "exp-textura_input_character_count",
  characterCountWarning: "exp-textura_input_character_count_warning",
  prefix: "exp-textura_input_prefix",
  suffix: "exp-textura_input_suffix",
  clearIconButton: "exp-textura_input_clear_icon_button",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    inputWrapper: {
      border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.critical.color.border.enabled}`,
      color: theme.inputText.critical.color.content.filled.enabled,
    },
    inputWrapperHover: {
      border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.critical.color.border.hover}`,
      color: theme.inputText.critical.color.content.filled.hover,
    },
    inputWrapperActive: {
      border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.critical.color.border.pressed}`,
      color: theme.inputText.critical.color.content.filled.pressed,
    },
    inputWrapperFocus: {
      border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.critical.color.border.pressed}`,
      color: theme.inputText.critical.color.content.filled.pressed,
    },
    inputWrapperDisabled: {
      border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.critical.color.border.disabled}`,
      color: theme.inputText.critical.color.content.filled.disabled,
    },
    input: {
      color: theme.inputText.critical.color.content.filled.enabled,

      "&::placeholder": {
        color: theme.inputText.critical.color.content.placeholder.enabled,
      },

      [`&:hover`]: {
        color: theme.inputText.critical.color.content.filled.hover,
        "&::placeholder": {
          color: theme.inputText.critical.color.content.placeholder.hover,
        },
      },

      [`&:active`]: {
        color: theme.inputText.critical.color.content.filled.pressed,
        "&::placeholder": {
          color: theme.inputText.critical.color.content.placeholder.pressed,
        },
      },

      "&[disabled]": {
        background: "transparent",
        boxShadow: "none",
        cursor: "not-allowed",
        color: theme.inputText.critical.color.content.filled.disabled,
        "&::placeholder": {
          color: theme.inputText.critical.color.content.placeholder.disabled,
        },
      },
    },
    placeholder: {
      color: theme.inputText.critical.color.content.placeholder.enabled,
    },
    prefix: {
      color: theme.inputText.critical.color.content.placeholder.enabled,
    },
    suffix: {
      color: theme.inputText.critical.color.content.placeholder.enabled,
    },
  },
  inline: {
    inputWrapper: {
      border: "none",
      color: theme.color.content.weak,
      fontWeight: 500,
    },
    inputWrapperHover: {
      border: "none",
      backgroundColor: theme.color.background.defaultHover,
      color: theme.color.content.default,
    },
    inputWrapperActive: {
      border: "none",
      backgroundColor: theme.color.background.defaultPressed,
      color: theme.color.content.default,
    },
    inputWrapperFocus: {
      border: "none",
      outline: "none",
      backgroundColor: theme.color.background.defaultPressed,
      color: theme.color.content.default,
    },
    inputWrapperDisabled: {
      border: "none",
      backgroundColor: "transparent",
    },
    input: {
      color: theme.color.content.weak,
      fontWeight: 500,

      "&::placeholder": {
        color: theme.color.content.weak,
      },

      [`&:hover`]: {
        color: theme.color.content.default,
      },

      [`&:active`]: {
        color: theme.color.content.default,
      },

      "&[disabled]": {
        color: theme.color.content.disabled,
      },
    },
  },
});

const generateStyles = (props: InputProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<InputProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    position: "relative",
    textTransform: "unset",
    width: "100%",

    [`.${InputClasses.inputWrapper}`]: {
      display: "flex",
      border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.default.color.border.enabled}`,
      borderRadius: theme.inputText.border.radius,
      padding: `0 ${theme.toRem(theme.spacing[8])}`,
      minWidth: theme.getSpacing(6),
      alignItems: "center",
      height: `${theme.toRem(32)}`,
      boxSizing: "border-box",
      gap: theme.toRem(theme.spacing[8]),
      color: theme.inputText.default.color.content.filled.enabled,
      ...theme.typography.body.md,

      [`&:hover:not([data-focus="true"]):not([data-disabled="true"])`]: {
        color: theme.inputText.default.color.content.filled.hover,
        borderColor: theme.inputText.default.color.border.hover,
        ...styleSlots?.inputWrapperHover,
      },

      [`&[data-active="true"]`]: {
        color: theme.inputText.default.color.content.filled.pressed,
        borderWidth: theme.toRem(theme.inputText.border.width),
        ...styleSlots?.inputWrapperActive,
      },

      [`&[data-disabled="true"]`]: {
        border: `${theme.toRem(theme.inputText.border.width)} solid ${theme.inputText.default.color.border.disabled}`,
        color: theme.inputText.default.color.content.filled.disabled,
        [`.${InputClasses.prefix}`]: {
          color: theme.inputText.default.color.content.placeholder.disabled,
          ...styleSlots?.prefixDisabled,
        },
        ...styleSlots?.inputWrapperDisabled,
      },

      [`&[data-focus="true"]`]: {
        outline: "none",
        borderColor: theme.inputText.default.color.border.pressed,
        borderWidth: theme.toRem(theme.inputText.border.width),
        ...styleSlots?.inputWrapperFocus,
      },

      ...styleSlots?.inputWrapper,
    },

    [`.${InputClasses.input}`]: {
      color: theme.inputText.default.color.content.filled.enabled,
      backgroundColor: "transparent",
      flex: 1,
      border: "none",
      outline: "none",
      padding: 0,
      alignSelf: "stretch",
      ...theme.typography.body.md,

      "&[type=date]": {
        WebkitAppearance: "none",
        "&::-webkit-calendar-picker-indicator": {
          display: "none",
          WebkitAppearance: "none",
        },
      },

      "&[type=number]": { MozAppearance: "textfield" },

      "&::placeholder": {
        color: theme.inputText.default.color.content.placeholder.enabled,
        ...styleSlots?.placeholder,
      },

      [`&:hover`]: {
        color: theme.inputText.default.color.content.filled.hover,
        "&::placeholder": {
          color: theme.inputText.default.color.content.placeholder.hover,
        },
      },

      [`&:active`]: {
        color: theme.inputText.default.color.content.filled.pressed,
        "&::placeholder": {
          color: theme.inputText.default.color.content.placeholder.pressed,
        },
      },

      "&[disabled]": {
        background: "transparent",
        boxShadow: "none",
        cursor: "not-allowed",
        color: theme.inputText.default.color.content.filled.disabled,
        "&::placeholder": {
          color: theme.inputText.default.color.content.placeholder.disabled,
        },
      },

      [`&:focus-visible`]: {
        outline: "none",
        boxShadow: "none",
      },

      ...styleSlots?.input,
    },

    [`.${InputClasses.characterCount}`]: {
      fontSize: theme.typography.fontSize[12],
      marginTop: theme.toRem(theme.spacing[4]),
      textAlign: "end",
      color: theme.color.content.weak,
      ...styleSlots?.characterCount,
    },

    [`.${InputClasses.characterCountWarning}`]: {
      color: theme.color.content.utility.critical,
      ...styleSlots?.characterCountWarning,
    },

    [`.${InputClasses.prefix}`]: {
      order: "-1",
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      color: theme.inputText.default.color.content.placeholder.enabled,
      ...styleSlots?.prefix,
    },

    [`.${InputClasses.suffix}`]: {
      order: "999",
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      color: theme.inputText.default.color.content.placeholder.enabled,
      ...styleSlots?.suffix,
    },

    [`&.${InputClasses.sm}`]: {
      ...theme.typography.body.sm,

      [`.${InputClasses.inputWrapper}`]: {
        height: theme.toRem(24),
        ...styleSlots?.inputWrapperSm,
      },

      [`.${InputClasses.input}`]: {
        ...theme.typography.body.sm,
      },
    },

    [`.${InputClasses.clearIconButton}`]: {
      marginInlineEnd: `calc(${theme.toRem(theme.spacing[8])} * -1)`,
      maxHeight: theme.toRem(30),
      ...styleSlots?.clearButton,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledInput = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<InputProps>((props) => generateStyles(props));
